const event = $json.action || $json;
const eventId = String(event.id || $json.id || '');
const type = String(event.type || '');
const data = event.data || {};
const boardId = String(data.board?.id || data.card?.idBoard || '');
const listAfterId = String(data.listAfter?.id || '');
const cardId = String(data.card?.id || '');
if (!eventId || !cardId || type !== 'updateCard' || boardId !== '62bae9b97705e7419ed64593' || listAfterId !== '6421a75cc602d9d540d59f2d') return [];
const sd = $getWorkflowStaticData('global');
const doneKey = 'done_card_' + cardId;
const processingKey = 'processing_card_' + cardId;
const now = Date.now();
if (sd[processingKey] && now - Number(sd[processingKey]) < 10 * 60 * 1000) return [];
sd[processingKey] = now;
return [{ json: { eventId, cardId, sourceBoardId: boardId, sourceListId: listAfterId } }];

const card = $json;
const event = $('Gate Exact Vector Event').first().json;
function classifyTitle(title) {
  const value = String(title || '').toLowerCase().replace(/[‐‑‒–—−_]/g, '-');
  if (/\b(?:led\s*-?\s*neon(?:\s*-?\s*flex)?|neon\s*-?\s*flex)\b/i.test(value)) return { kind: 'led-neon-flex', destinationListId: '6421a72719c7af9056e6d16b', known: true };
  const rules = [
    ['3d-backlit', /\b(?:3d\s*-?\s*)?back\s*-?\s*lit\b/i], ['3d-frontlit', /\b(?:3d\s*-?\s*)?front\s*-?\s*lit\b/i],
    ['3d-nonlit', /\b(?:3d\s*-?\s*)?non\s*-?\s*lit\b/i], ['3d-other', /\b3d\b/i],
    ['lightbox', /\blight\s*-?\s*box\b/i],
    ['ultra-thin-acrylic', /\bultra\s*-?\s*thin\s+acrylic\b/i], ['neon-halo', /\bneon\s*-?\s*halo\b/i],
    ['full-glow', /\bfull\s*-?\s*glow\b/i], ['marquee', /\bmarquee?\b/i],
  ];
  const found = rules.find(([, regex]) => regex.test(value));
  if (found) return { kind: found[0], destinationListId: '659ffc4e5f8bffd67fe38265', known: true };
  return { kind: 'led-neon-flex', destinationListId: '6421a72719c7af9056e6d16b', known: true, defaulted: true };
}
const route = classifyTitle(card.name);
const MARKER_PREFIX = '<!-- NEONTRIP_QUENTIN_COPY:v1 source=';
function parseCopyMarker(text) {
  const value = String(text || '');
  const start = value.indexOf(MARKER_PREFIX);
  if (start < 0) return null;
  const body = value.slice(start + MARKER_PREFIX.length);
  const end = body.indexOf(' -->');
  if (end < 0) return null;
  const parts = body.slice(0, end).split(' target=');
  if (parts.length !== 2 || !parts[0] || !parts[1]) return null;
  return { sourceId: parts[0].trim(), targetId: parts[1].trim() };
}
const sourceActions = Array.isArray(card.actions) ? card.actions : [];
let existingCopyTargetId = '';
for (const action of sourceActions) {
  const parsed = parseCopyMarker(action?.data?.text);
  if (parsed && parsed.sourceId === String(card.id) && parsed.targetId) {
    existingCopyTargetId = parsed.targetId;
    break;
  }
}
const attachments = Array.isArray(card.attachments) ? card.attachments : [];
const image = attachments.filter(a => /^image\.png$/i.test(String(a.name || '').trim())).sort((a,b) => String(b.date || '').localeCompare(String(a.date || '')))[0] || null;
const fieldValues = Object.fromEntries((card.customFieldItems || []).map(item => [item.idCustomField, item.value?.text ?? item.value?.number ?? '']));
const attachmentSignature = attachments.map(a => [String(a.name || ''), Number(a.bytes || 0), String(a.mimeType || '')].join('|')).sort();
const customFieldCount = Array.isArray(card.customFieldItems) ? card.customFieldItems.length : 0;
return [{ json: {
  ...event,
  cardId: card.id,
  cardName: card.name || '',
  cardDescription: card.desc || '',
  cardUrl: card.url || '',
  route,
  existingCopyTargetId,
  imageUrl: image?.url || '',
  imageAttachmentId: image?.id || '',
  fieldValues,
  sourceSnapshot: {
    attachmentSignature,
    checklistCount: Array.isArray(card.idChecklists) ? card.idChecklists.length : 0,
    customFieldCount,
    commentCount: Number(card.badges?.comments || 0)
  }
} }];

const ctx = $('Prepare Card Context').first().json;
let dataUrl = '';
try {
  const buffer = await $getBinaryDataBuffer(0, 'image');
  if (buffer?.length) dataUrl = 'data:image/png;base64,' + buffer.toString('base64');
} catch (error) {}
const prompt = [
  'Read this supplier technical drawing. Return strict JSON only.',
  'Identify every product/size variant, maximum four. Preserve visual reading order: design groups top-to-bottom and left-to-right; variants inside each group left-to-right/top-to-bottom.',
  'For each variant return: reading_order (1-based integer), design_index (1-based integer), size_index (1-based within design), total (number or null), backboard_raw (exact English phrase or empty), confidence (0..1).',
  'The price to extract is Total, never Production Price and never Shipping cost.',
  'Do not invent unreadable values. issues must list uncertainties.',
  'Schema: {"variants":[{"reading_order":1,"design_index":1,"size_index":1,"total":117,"backboard_raw":"Cut to shape","confidence":0.99}],"issues":[]}'
].join('\n');
const body = {
  model: 'gpt-4o', temperature: 0,
  response_format: { type: 'json_object' },
  messages: [{ role: 'user', content: dataUrl ? [{ type: 'text', text: prompt }, { type: 'image_url', image_url: { url: dataUrl, detail: 'high' } }] : [{ type: 'text', text: prompt + '\nNo image was available; return empty variants and an issue.' }] }]
};
return [{ json: { ...ctx, body } }];

const ctx = $('Prepare Card Context').first().json;
const BACKBOARD_IDS = ['67ab34664610ec7a48dd3e25','67ab34753b38d5d627c00406','67f4f919135f6ee95dcfafc1','67f4f96efd792feaa9b0c1df'];
const PRICE_IDS = ['67ab4036913a9ecdc0cb3a30','67ab404384a17910e9673e48','67f4f8f054ff1b3f888c0228','67f4f933dd18fd2f77bf8708'];
function translate(raw, kind) {
  const value = String(raw || '').toLowerCase().trim().replace(/[‐‑‒–—−_]/g, ' ');
  if (kind === 'led-neon-flex') {
    if (/cut\s*to\s*shape|shape\s*cut/.test(value)) return { value: 'Formzuschnitt' };
    if (/cut\s*to\s*(?:letter|letters)|fine\s*cut/.test(value)) return { value: 'Feinzuschnitt' };
    if (/cut\s*to\s*(?:board|rectangle)|rectangular\s*cut/.test(value)) return { value: 'Rechteckiger Zuschnitt' };
    return { value: '' };
  }
  return { value: /loose\s*letters?/.test(value) ? 'Einzelne Buchstaben' : '' };
}
function money(value) {
  if (value === null || value === undefined || value === '') return { value: null };
  const number = Number(String(value).replace(/[^0-9,.-]/g, '').replace(',', '.'));
  return { value: Number.isFinite(number) ? Math.round(number * 100) / 100 : null };
}
let proposal = { variants: [], issues: [] };
const warnings = [];
try {
  const raw = $json.choices?.[0]?.message?.content;
  proposal = JSON.parse(String(raw || '{}'));
} catch (error) { warnings.push('image.png konnte nicht zuverlässig ausgewertet werden'); }
let variants = Array.isArray(proposal.variants) ? proposal.variants : [];
variants = variants.filter(v => Number.isInteger(Number(v.reading_order)) && Number(v.reading_order) >= 1).sort((a,b) => Number(a.reading_order)-Number(b.reading_order));
if (!ctx.imageUrl) warnings.push('image.png fehlt');
if (!variants.length) warnings.push('keine sicher zuordenbare Variante aus image.png');
if (variants.length > 4) warnings.push((variants.length - 4) + ' weitere Variante(n) passen nicht in die vier Trello-Felder');
if (Array.isArray(proposal.issues)) {
  for (const issue of proposal.issues) {
    const text = String(issue || '').trim();
    if (text) warnings.push(text);
  }
}
const fieldOps = [];
let mismatch = false;
for (let index = 0; index < 4; index += 1) {
  const variant = variants[index];
  const value = variant ? translate(variant.backboard_raw, ctx.route.kind).value : '';
  if (variant && !value) warnings.push('Backboard_' + (index + 1) + ' konnte nicht sicher ausgelesen werden');
  const existingBackboard = String(ctx.fieldValues[BACKBOARD_IDS[index]] || '');
  fieldOps.push({ fieldId: BACKBOARD_IDS[index], value: value || existingBackboard });
  if (variant && money(variant.total).value !== null) {
    const current = money(ctx.fieldValues[PRICE_IDS[index]]).value;
    if (current === null || Math.abs(current - money(variant.total).value) > 0.009) mismatch = true;
  } else if (variant) warnings.push('Total für Price_' + (index + 1) + ' konnte nicht sicher ausgelesen werden');
}
if (ctx.route.kind !== 'led-neon-flex' && !variants.length) warnings.push('Neon-Zuschnittswerte wurden bei einem Nicht-Neon-Produkt entfernt');
const uniqueWarnings = [];
for (const warning of warnings) {
  const text = String(warning || '').trim();
  if (text && !uniqueWarnings.includes(text)) uniqueWarnings.push(text);
}
const titleFlags = [];
if (mismatch || uniqueWarnings.some(w => /(?:total|price|preis)/i.test(w))) titleFlags.push('Preise prüfen');
if (uniqueWarnings.some(w => /(?:backboard|zuschnitt|image\.png|variante)/i.test(w))) titleFlags.push('Formzuschnitt prüfen');
if (uniqueWarnings.length && titleFlags.length === 0) titleFlags.push('Angaben prüfen');
const cleanTitle = ctx.cardName.replace(/\s+❗\s+(?:(?:Preise|Formzuschnitt|Angaben) prüfen)(?:\s*\/\s*(?:(?:Preise|Formzuschnitt|Angaben) prüfen))*\s*$/i, '');
const newTitle = titleFlags.length ? cleanTitle + ' ❗ ' + titleFlags.join(' / ') : ctx.cardName;
const output = [];
for (const op of fieldOps) output.push({ json: { ...ctx, ...op, mismatch, newTitle, warnings: uniqueWarnings } });
return output;

const plan = $('Plan Safe Field Operations').first().json;
const failedFields = $input.all().filter(item => item.json?.error).length;
const warnings = [...(plan.warnings || [])];
if (failedFields) warnings.push(failedFields + ' Backboard-Feld(er) konnten technisch nicht aktualisiert werden');
const unique = [...new Set(warnings)];
return [{ json: { ...plan, warnings: unique, needsComment: unique.length > 0, commentText: '❗ TICKET-103 [' + plan.eventId + '] ' + unique.join('; ') } }];

const plan = $('Finalize Advisory Results').first().json;
const source = $('Prepare Card Context').first().json;
const copied = $json;
const expectedMarker = '<!-- NEONTRIP_QUENTIN_COPY:v1 source=' + plan.cardId + ' target=' + String(copied?.id || '') + ' -->';
const copiedActions = Array.isArray(copied?.actions) ? copied.actions : [];
if (!copiedActions.some(action => String(action?.data?.text || '').includes(expectedMarker))) throw new Error('Exact target copy marker verification failed');
if (!copied?.id || String(copied.idList || '') !== String(plan.route.destinationListId)) {
  throw new Error('Target card was not created in the required list');
}
const verificationWarnings = [];
const copiedAttachmentSignature = (Array.isArray(copied.attachments) ? copied.attachments : [])
  .map(a => [String(a.name || ''), Number(a.bytes || 0), String(a.mimeType || '')].join('|'))
  .sort();
if (JSON.stringify(copiedAttachmentSignature) !== JSON.stringify(source.sourceSnapshot.attachmentSignature)) verificationWarnings.push('attachments differ');
if (String(copied.desc || '') !== String(source.cardDescription || '')) verificationWarnings.push('description differs');
const copiedChecklistCount = Array.isArray(copied.idChecklists) ? copied.idChecklists.length : 0;
if (copiedChecklistCount !== source.sourceSnapshot.checklistCount) verificationWarnings.push('checklists differ');
const copiedCustomFieldCount = Array.isArray(copied.customFieldItems) ? copied.customFieldItems.length : 0;
if (copiedCustomFieldCount !== source.sourceSnapshot.customFieldCount) verificationWarnings.push('custom field count differs');
if (Number(copied.badges?.comments || 0) < source.sourceSnapshot.commentCount) verificationWarnings.push('comments missing');
const sd = $getWorkflowStaticData('global');
sd['done_card_' + plan.cardId] = {
  at: new Date().toISOString(),
  eventId: plan.eventId,
  copiedCardId: String(copied.id)
};
sd['done_' + plan.eventId] = new Date().toISOString();
delete sd['processing_card_' + plan.cardId];
delete sd['processing_' + plan.eventId];
return [{ json: {
  status: 'copied',
  eventId: plan.eventId,
  sourceCardId: plan.cardId,
  sourceCardUrl: plan.cardUrl,
  copiedCardId: String(copied.id),
  copiedCardUrl: String(copied.url || ''),
  destinationListId: String(copied.idList || ''),
  warningTitle: plan.newTitle,
  advisoryWarnings: plan.warnings || [],
  verificationWarnings,
  attachmentCount: copiedAttachmentSignature.length
} }];

const source = $('Prepare Card Context').first().json;
const target = $json;
const expected = '<!-- NEONTRIP_QUENTIN_COPY:v1 source=' + source.cardId + ' target=' + source.existingCopyTargetId + ' -->';
if (String(target?.id || '') !== String(source.existingCopyTargetId || '')) throw new Error('Stored copy marker does not resolve to the exact target card');
const actions = Array.isArray(target.actions) ? target.actions : [];
const hasExactTargetMarker = actions.some(action => String(action?.data?.text || '').includes(expected));
return [{ json: { ...target, hasExactTargetMarker, exactCopyMarkerText: 'Kopie\n\n' + expected } }];

const source = $('Prepare Card Context').first().json;
const sd = $getWorkflowStaticData('global');
