delete sd['processing_' + source.eventId];
return [{ json: { status: 'already-copied', eventId: source.eventId, sourceCardId: source.cardId, sourceCardUrl: source.cardUrl, copiedCardId: source.existingCopyTargetId, repairedTargetMarker: $('Check Target Self Marker').first().json.hasExactTargetMarker === false } }];
